//! `unitree_go::msg::dds_` types (Go2, Go2-W, B2, B2-W, A2, AS2 and the
//! original H1 low-level interface).
//!
//! Field order and types follow
//! `unitree_sdk2/include/unitree/idl/go2/*.hpp` (generated by the Cyclone
//! DDS IDL-to-C++ translator v0.10.2), cross-checked against
//! `unitree_ros2/cyclonedds_ws/src/unitree/unitree_go/msg/*.msg`. Where the
//! two disagree on signedness of an 8-bit field (the SDK says `uint8_t`,
//! the `.msg` says `int8` for temperatures and NTC readings), the bytes are
//! the same and the `.msg` signedness is used. `SportModeState_` has a
//! trailing `PathPoint_[10] path_point` in the SDK IDL (and the Python
//! SDK) that the ROS 2 `.msg` lacks; it is decoded when present
//! ([`GoSportModeState::path_point`]).
//!
//! The SDK's TypeObjects mark these structs `@final` (struct flags `0x01`
//! in the type-information blobs), so a writer is expected to send XCDR1
//! (`CDR_LE`) or plain XCDR2 (`CDR2_LE`); both decode, and so does `D_CDR2`
//! under the crate's [`crate::Limits::d_cdr2_nesting`] rule.

use crate::error::DecodeError;
use crate::msgs::Time;
use crate::reader::Reader;
use crate::unitree::crc::CrcImage;
use crate::unitree::joint::{JointCommand, JointCommandFrame, JointMeasurement, JointStateFrame};
use crate::unitree::{arr, read_struct_array, MOTOR_SLOTS_GO};

/// `unitree_go::msg::dds_::MotorCmd_`.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct GoMotorCmd {
    pub mode: u8,
    pub q: f32,
    pub dq: f32,
    pub tau: f32,
    pub kp: f32,
    pub kd: f32,
    pub reserve: [u32; 3],
}

impl GoMotorCmd {
    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoMotorCmd {
                mode: r.u8()?,
                q: r.f32()?,
                dq: r.f32()?,
                tau: r.f32()?,
                kp: r.f32()?,
                kd: r.f32()?,
                reserve: arr(r, Reader::u32)?,
            })
        })
    }

    fn image(&self, img: &mut CrcImage) {
        img.pad(4);
        img.u8(self.mode);
        img.f32(self.q);
        img.f32(self.dq);
        img.f32(self.tau);
        img.f32(self.kp);
        img.f32(self.kd);
        for v in self.reserve {
            img.u32(v);
        }
    }

    pub fn joint(&self) -> JointCommand {
        JointCommand {
            mode: self.mode,
            q: self.q,
            dq: self.dq,
            tau: self.tau,
            kp: self.kp,
            kd: self.kd,
        }
    }
}

/// `unitree_go::msg::dds_::BmsCmd_`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct GoBmsCmd {
    /// `0xA5` turns the battery off (legacy `comm.h` comment).
    pub off: u8,
    pub reserve: [u8; 3],
}

impl GoBmsCmd {
    fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoBmsCmd {
                off: r.u8()?,
                reserve: arr(r, Reader::u8)?,
            })
        })
    }
}

/// `unitree_go::msg::dds_::LowCmd_` (topic `rt/lowcmd`; `rt/arm_sdk` on
/// the original H1).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GoLowCmd {
    pub head: [u8; 2],
    pub level_flag: u8,
    pub frame_reserve: u8,
    pub sn: [u32; 2],
    pub version: [u32; 2],
    pub bandwidth: u16,
    pub motor_cmd: [GoMotorCmd; MOTOR_SLOTS_GO],
    pub bms_cmd: GoBmsCmd,
    pub wireless_remote: [u8; 40],
    pub led: [u8; 12],
    pub fan: [u8; 2],
    pub gpio: u8,
    pub reserve: u32,
    pub crc: u32,
}

impl GoLowCmd {
    /// C++ `sizeof(unitree_go::msg::dds_::LowCmd_)` (the Python SDK's
    /// `__packFmtLowCmd`, "size 812").
    pub const IMAGE_SIZE: usize = 812;

    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoLowCmd {
                head: arr(r, Reader::u8)?,
                level_flag: r.u8()?,
                frame_reserve: r.u8()?,
                sn: arr(r, Reader::u32)?,
                version: arr(r, Reader::u32)?,
                bandwidth: r.u16()?,
                motor_cmd: read_struct_array(r, GoMotorCmd::read)?,
                bms_cmd: GoBmsCmd::read(r)?,
                wireless_remote: arr(r, Reader::u8)?,
                led: arr(r, Reader::u8)?,
                fan: arr(r, Reader::u8)?,
                gpio: r.u8()?,
                reserve: r.u32()?,
                crc: r.u32()?,
            })
        })
    }

    /// The CRC the SDK computes for this message (`crc32_core` over the
    /// 812-byte C++ image minus the `crc` word).
    pub fn computed_crc(&self) -> u32 {
        let mut img = CrcImage::new();
        img.bytes(&self.head);
        img.u8(self.level_flag);
        img.u8(self.frame_reserve);
        for v in self.sn.iter().chain(&self.version) {
            img.u32(*v);
        }
        img.u16(self.bandwidth);
        for m in &self.motor_cmd {
            m.image(&mut img);
        }
        img.u8(self.bms_cmd.off);
        img.bytes(&self.bms_cmd.reserve);
        img.bytes(&self.wireless_remote);
        img.bytes(&self.led);
        img.bytes(&self.fan);
        img.u8(self.gpio);
        img.u32(self.reserve);
        debug_assert_eq!(img.len(), Self::IMAGE_SIZE - 4);
        img.finish()
    }

    /// `crc == computed_crc()`. A firewall can require this: the robot's
    /// motor controller rejects frames whose CRC does not match.
    pub fn crc_ok(&self) -> bool {
        self.crc == self.computed_crc()
    }

    /// All 20 motor slots as a [`JointCommandFrame`].
    pub fn joint_frame(&self) -> JointCommandFrame {
        let mut f = JointCommandFrame::default();
        for m in &self.motor_cmd {
            f.joints.push(m.joint());
        }
        f
    }
}

/// `unitree_go::msg::dds_::IMUState_`.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct GoImuState {
    /// (w, x, y, z), normalised (legacy `comm.h` comment).
    pub quaternion: [f32; 4],
    /// rad/s.
    pub gyroscope: [f32; 3],
    /// m/s².
    pub accelerometer: [f32; 3],
    /// rad.
    pub rpy: [f32; 3],
    pub temperature: i8,
}

impl GoImuState {
    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoImuState {
                quaternion: arr(r, Reader::f32)?,
                gyroscope: arr(r, Reader::f32)?,
                accelerometer: arr(r, Reader::f32)?,
                rpy: arr(r, Reader::f32)?,
                temperature: r.i8()?,
            })
        })
    }

    fn image(&self, img: &mut CrcImage) {
        img.pad(4);
        for v in self
            .quaternion
            .iter()
            .chain(&self.gyroscope)
            .chain(&self.accelerometer)
            .chain(&self.rpy)
        {
            img.f32(*v);
        }
        img.i8(self.temperature);
        img.pad(4);
    }
}

/// `unitree_go::msg::dds_::MotorState_`.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct GoMotorState {
    pub mode: u8,
    pub q: f32,
    pub dq: f32,
    pub ddq: f32,
    pub tau_est: f32,
    pub q_raw: f32,
    pub dq_raw: f32,
    pub ddq_raw: f32,
    pub temperature: i8,
    pub lost: u32,
    pub reserve: [u32; 2],
}

impl GoMotorState {
    fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoMotorState {
                mode: r.u8()?,
                q: r.f32()?,
                dq: r.f32()?,
                ddq: r.f32()?,
                tau_est: r.f32()?,
                q_raw: r.f32()?,
                dq_raw: r.f32()?,
                ddq_raw: r.f32()?,
                temperature: r.i8()?,
                lost: r.u32()?,
                reserve: arr(r, Reader::u32)?,
            })
        })
    }

    fn image(&self, img: &mut CrcImage) {
        img.pad(4);
        img.u8(self.mode);
        for v in [
            self.q,
            self.dq,
            self.ddq,
            self.tau_est,
            self.q_raw,
            self.dq_raw,
            self.ddq_raw,
        ] {
            img.f32(v);
        }
        img.i8(self.temperature);
        img.u32(self.lost);
        for v in self.reserve {
            img.u32(v);
        }
    }

    pub fn measurement(&self) -> JointMeasurement {
        JointMeasurement {
            mode: self.mode,
            q: self.q,
            dq: self.dq,
            ddq: self.ddq,
            tau_est: self.tau_est,
        }
    }
}

/// `unitree_go::msg::dds_::BmsState_`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct GoBmsState {
    pub version_high: u8,
    pub version_low: u8,
    pub status: u8,
    pub soc: u8,
    /// mA.
    pub current: i32,
    pub cycle: u16,
    pub bq_ntc: [i8; 2],
    pub mcu_ntc: [i8; 2],
    /// mV.
    pub cell_vol: [u16; 15],
}

impl GoBmsState {
    fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoBmsState {
                version_high: r.u8()?,
                version_low: r.u8()?,
                status: r.u8()?,
                soc: r.u8()?,
                current: r.i32()?,
                cycle: r.u16()?,
                bq_ntc: arr(r, Reader::i8)?,
                mcu_ntc: arr(r, Reader::i8)?,
                cell_vol: arr(r, Reader::u16)?,
            })
        })
    }

    fn image(&self, img: &mut CrcImage) {
        img.pad(4);
        img.bytes(&[self.version_high, self.version_low, self.status, self.soc]);
        img.i32(self.current);
        img.u16(self.cycle);
        for v in self.bq_ntc.iter().chain(&self.mcu_ntc) {
            img.i8(*v);
        }
        for v in self.cell_vol {
            img.u16(v);
        }
        img.pad(4);
    }
}

/// `unitree_go::msg::dds_::LowState_` (topic `rt/lowstate`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GoLowState {
    pub head: [u8; 2],
    pub level_flag: u8,
    pub frame_reserve: u8,
    pub sn: [u32; 2],
    pub version: [u32; 2],
    pub bandwidth: u16,
    pub imu_state: GoImuState,
    pub motor_state: [GoMotorState; MOTOR_SLOTS_GO],
    pub bms_state: GoBmsState,
    pub foot_force: [i16; 4],
    pub foot_force_est: [i16; 4],
    pub tick: u32,
    pub wireless_remote: [u8; 40],
    pub bit_flag: u8,
    pub adc_reel: f32,
    pub temperature_ntc1: i8,
    pub temperature_ntc2: i8,
    pub power_v: f32,
    pub power_a: f32,
    pub fan_frequency: [u16; 4],
    pub reserve: u32,
    pub crc: u32,
}

impl GoLowState {
    /// C++ `sizeof(unitree_go::msg::dds_::LowState_)` (Python SDK
    /// `__packFmtLowState`, "size 1180").
    pub const IMAGE_SIZE: usize = 1180;

    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoLowState {
                head: arr(r, Reader::u8)?,
                level_flag: r.u8()?,
                frame_reserve: r.u8()?,
                sn: arr(r, Reader::u32)?,
                version: arr(r, Reader::u32)?,
                bandwidth: r.u16()?,
                imu_state: GoImuState::read(r)?,
                motor_state: read_struct_array(r, GoMotorState::read)?,
                bms_state: GoBmsState::read(r)?,
                foot_force: arr(r, Reader::i16)?,
                foot_force_est: arr(r, Reader::i16)?,
                tick: r.u32()?,
                wireless_remote: arr(r, Reader::u8)?,
                bit_flag: r.u8()?,
                adc_reel: r.f32()?,
                temperature_ntc1: r.i8()?,
                temperature_ntc2: r.i8()?,
                power_v: r.f32()?,
                power_a: r.f32()?,
                fan_frequency: arr(r, Reader::u16)?,
                reserve: r.u32()?,
                crc: r.u32()?,
            })
        })
    }

    /// The CRC the SDK computes for this message.
    pub fn computed_crc(&self) -> u32 {
        let mut img = CrcImage::new();
        img.bytes(&self.head);
        img.u8(self.level_flag);
        img.u8(self.frame_reserve);
        for v in self.sn.iter().chain(&self.version) {
            img.u32(*v);
        }
        img.u16(self.bandwidth);
        self.imu_state.image(&mut img);
        for m in &self.motor_state {
            m.image(&mut img);
        }
        self.bms_state.image(&mut img);
        for v in self.foot_force.iter().chain(&self.foot_force_est) {
            img.i16(*v);
        }
        img.u32(self.tick);
        img.bytes(&self.wireless_remote);
        img.u8(self.bit_flag);
        img.f32(self.adc_reel);
        img.i8(self.temperature_ntc1);
        img.i8(self.temperature_ntc2);
        img.f32(self.power_v);
        img.f32(self.power_a);
        for v in self.fan_frequency {
            img.u16(v);
        }
        img.u32(self.reserve);
        debug_assert_eq!(img.len(), Self::IMAGE_SIZE - 4);
        img.finish()
    }

    pub fn crc_ok(&self) -> bool {
        self.crc == self.computed_crc()
    }

    /// All 20 motor slots as a [`JointStateFrame`].
    pub fn joint_frame(&self) -> JointStateFrame {
        let mut f = JointStateFrame::default();
        for m in &self.motor_state {
            f.joints.push(m.measurement());
        }
        f
    }
}

