/// `unitree_go::msg::dds_::SportModeState_` (topics `rt/sportmodestate`,
/// `rt/lf/sportmodestate`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GoSportModeState {
    /// `TimeSpec_` stamp: a wire claim, not used as the event time.
    pub stamp: Time,
    pub error_code: u32,
    pub imu_state: GoImuState,
    pub mode: u8,
    pub progress: f32,
    pub gait_type: u8,
    pub foot_raise_height: f32,
    /// m (odometry; the frame is not documented in the SDK headers).
    pub position: [f32; 3],
    pub body_height: f32,
    /// m/s (vx, vy, vz). The legacy `comm.h` documents the equivalent
    /// `HighState::velocity` as body frame; the SDK2 headers say nothing.
    pub velocity: [f32; 3],
    /// rad/s.
    pub yaw_speed: f32,
    pub range_obstacle: [f32; 4],
    pub foot_force: [i16; 4],
    pub foot_position_body: [f32; 12],
    pub foot_speed_body: [f32; 12],
    /// `PathPoint_[10]` of the SDK IDL, `None` when the sample ends before
    /// it (the ROS 2 `.msg` definition has no such member).
    pub path_point: Option<[GoPathPoint; 10]>,
}

impl GoSportModeState {
    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            let stamp = r.structure(|r| {
                Ok(Time {
                    sec: r.i32()?,
                    nanosec: r.u32()?,
                })
            })?;
            let mut s = GoSportModeState {
                stamp,
                error_code: r.u32()?,
                imu_state: GoImuState::read(r)?,
                mode: r.u8()?,
                progress: r.f32()?,
                gait_type: r.u8()?,
                foot_raise_height: r.f32()?,
                position: arr(r, Reader::f32)?,
                body_height: r.f32()?,
                velocity: arr(r, Reader::f32)?,
                yaw_speed: r.f32()?,
                range_obstacle: arr(r, Reader::f32)?,
                foot_force: arr(r, Reader::i16)?,
                foot_position_body: arr(r, Reader::f32)?,
                foot_speed_body: arr(r, Reader::f32)?,
                path_point: None,
            };
            // The SDK IDL's trailing PathPoint_[10] is read only if the
            // sample is long enough for it; otherwise the bytes left (end
            // padding at most, for the .msg layout) stay trailing bytes.
            let mut probe = r.clone();
            if let Ok(pp) = read_struct_array(&mut probe, GoPathPoint::read) {
                *r = probe;
                s.path_point = Some(pp);
            }
            Ok(s)
        })
    }
}

/// `unitree_go::msg::dds_::WirelessController_` (topic
/// `rt/wirelesscontroller`, `example/wireless_controller/main.cpp`): the
/// remote's sticks and keys as reported by the robot. Not a motion message.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct GoWirelessController {
    pub lx: f32,
    pub ly: f32,
    pub rx: f32,
    pub ry: f32,
    pub keys: u16,
}

impl GoWirelessController {
    pub(crate) fn read(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.structure(|r| {
            Ok(GoWirelessController {
                lx: r.f32()?,
                ly: r.f32()?,
                rx: r.f32()?,
                ry: r.f32()?,
                keys: r.u16()?,
            })
        })
    }
}
